    public static long invl(long a, long mod) {
        long b = mod, p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d = a;
            a = b;
            b = d % b;
            long temp = p;
            p = q;
            q = temp - c * q;
        }
        return p < 0 ? p + mod : p;
